CREATE TABLE "servicio" ( "id_servicio" BIGINT NOT NULL, "nombre" VARCHAR(120) NOT NULL, "categoria" VARCHAR(80) NULL, "elegible_fidelidad" BOOLEAN NOT NULL, "elegible_cumpleanos" BOOLEAN NOT NULL, "activo" BOOLEAN NOT NULL, "created_at" TIMESTAMPTZ NOT NULL, "updated_at" TIMESTAMPTZ NULL, PRIMARY KEY ("id_servicio") ); CREATE TABLE "cuadre_caja" ( "id_cuadre_caja" BIGINT NOT NULL, "id_sucursal" BIGINT NOT NULL, "id_cerrado_por" BIGINT NOT NULL, "idempotency_key" UUID NOT NULL UNIQUE, "periodo_inicio" TIMESTAMPTZ NOT NULL, "periodo_fin" TIMESTAMPTZ NOT NULL CHECK (periodo_fin >= periodo_inicio), "efectivo_esperado" NUMERIC(12,2) NOT NULL, "efectivo_contado" NUMERIC(12,2) NOT NULL, "diferencia" NUMERIC(12,2) NOT NULL, "explicacion_diferencia" TEXT NULL, "estado" VARCHAR(30) NOT NULL, "fecha_hora_cierre" TIMESTAMPTZ NULL, "created_at" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("id_cuadre_caja") ); CREATE TABLE "servicio_precio_historial" ( "id_servicio_precio" BIGINT NOT NULL, "id_servicio" BIGINT NOT NULL, "precio" NUMERIC(12,2) NOT NULL CHECK (precio >= 0), "vigencia_desde" TIMESTAMPTZ NOT NULL, "vigencia_hasta" TIMESTAMPTZ NULL, "created_at" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("id_servicio_precio") ); CREATE TABLE "rol" ( "id_rol" BIGINT NOT NULL, "codigo" VARCHAR(40) NOT NULL UNIQUE, "nombre" VARCHAR(80) NOT NULL, "activo" BOOLEAN NOT NULL, PRIMARY KEY ("id_rol") ); CREATE TABLE "usuario" ( "id_usuario" BIGINT NOT NULL, "id_rol" BIGINT NOT NULL, "firebase_uid" VARCHAR(128) NOT NULL UNIQUE, "nombre_completo" VARCHAR(150) NOT NULL, "activo" BOOLEAN NOT NULL, "created_at" TIMESTAMPTZ NOT NULL, "updated_at" TIMESTAMPTZ NULL, PRIMARY KEY ("id_usuario"), CONSTRAINT "FK_usuario_firebase_uid" FOREIGN KEY ("firebase_uid") REFERENCES "rol"("codigo") ); CREATE TABLE "gasto" ( "id_gasto" BIGINT NOT NULL, "id_sucursal" BIGINT NOT NULL, "id_registrado_por" BIGINT NOT NULL, "id_metodo_pago" BIGINT NOT NULL, "id_banco" BIGINT NULL, "idempotency_key" UUID NOT NULL UNIQUE, "fecha_hora" TIMESTAMPTZ NOT NULL, "categoria" VARCHAR(100) NOT NULL, "descripcion" VARCHAR(250) NOT NULL, "monto" NUMERIC(12,2) NOT NULL CHECK (monto > 0), "observacion" TEXT NULL, "created_at" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("id_gasto"), CONSTRAINT "FK_gasto_idempotency_key" FOREIGN KEY ("idempotency_key") REFERENCES "usuario"("updated_at") ); CREATE TABLE "cliente" ( "id_cliente" BIGINT NOT NULL, "nombre_completo" VARCHAR(150) NOT NULL INDEX, "telefono" VARCHAR(30) NOT NULL INDEX, "fecha_nacimiento" DATE NOT NULL, "created_at" TIMESTAMPTZ NOT NULL, "updated_at" TIMESTAMPTZ NULL, PRIMARY KEY ("id_cliente") ); CREATE TABLE "sucursal" ( "id_sucursal" BIGINT NOT NULL, "nombre" VARCHAR(100) NOT NULL UNIQUE, "activo" BOOLEAN NOT NULL, "created_at" TIMESTAMPTZ NOT NULL, "updated_at" TIMESTAMPTZ NULL, PRIMARY KEY ("id_sucursal") ); CREATE TABLE "cita" ( "id_cita" BIGINT NOT NULL, "id_cliente" BIGINT NOT NULL, "id_sucursal" BIGINT NOT NULL, "id_barbero" BIGINT NOT NULL, "id_creada_por" BIGINT NOT NULL, "fecha_hora" TIMESTAMPTZ NOT NULL, "estado" VARCHAR(30) NOT NULL, "observaciones" TEXT NULL, "created_at" TIMESTAMPTZ NOT NULL, "updated_at" TIMESTAMPTZ NULL, PRIMARY KEY ("id_cita"), CONSTRAINT "FK_cita_id_cita" FOREIGN KEY ("id_cita") REFERENCES "sucursal"("updated_at") ); CREATE TABLE "operacion" ( "id_operacion" BIGINT NOT NULL, "id_cliente" BIGINT NOT NULL, "id_cita" BIGINT NULL UNIQUE WHEN NOT NULL, "id_sucursal" BIGINT NOT NULL, "id_barbero" BIGINT NULL, "id_registrada_por" BIGINT NOT NULL, "id_cuadre_caja" BIGINT NULL, "idempotency_key" UUID NOT NULL UNIQUE, "fecha_hora" TIMESTAMPTZ NOT NULL, "estado" VARCHAR(30) NOT NULL, "total_bruto" NUMERIC(12,2) NOT NULL CHECK (total_bruto >= 0), "total_descuentos" NUMERIC(12,2) NOT NULL CHECK (total_descuentos >= 0), "total_cobrado" NUMERIC(12,2) NOT NULL CHECK (total_cobrado >= 0), "observaciones" TEXT NULL, "created_at" TIMESTAMPTZ NOT NULL, "updated_at" TIMESTAMPTZ NULL, PRIMARY KEY ("id_operacion"), CONSTRAINT "FK_operacion_id_operacion" FOREIGN KEY ("id_operacion") REFERENCES "usuario"("id_rol"), CONSTRAINT "FK_operacion_id_barbero" FOREIGN KEY ("id_barbero") REFERENCES "usuario"("id_rol"), CONSTRAINT "FK_operacion_idempotency_key" FOREIGN KEY ("idempotency_key") REFERENCES "cliente"("updated_at"), CONSTRAINT "FK_operacion_total_bruto" FOREIGN KEY ("total_bruto") REFERENCES "cita"("created_at") ); CREATE TABLE "regla_comision" ( "id_regla_comision" BIGINT NOT NULL, "id_servicio" BIGINT NULL, "nombre" VARCHAR(120) NOT NULL, "circunstancia" VARCHAR(150) NULL, "tipo_calculo" VARCHAR(30) NOT NULL, "valor" NUMERIC(12,2) NOT NULL CHECK (valor >= 0), "vigencia_desde" TIMESTAMPTZ NOT NULL, "vigencia_hasta" TIMESTAMPTZ NULL, "activo" BOOLEAN NOT NULL, PRIMARY KEY ("id_regla_comision"), CONSTRAINT "FK_regla_comision_id_regla_comision" FOREIGN KEY ("id_regla_comision") REFERENCES "servicio"("created_at") ); CREATE TABLE "motivo_gratuidad" ( "id_motivo_gratuidad" BIGINT NOT NULL, "codigo" VARCHAR(50) NOT NULL UNIQUE, "nombre" VARCHAR(100) NOT NULL, "activo" BOOLEAN NOT NULL, PRIMARY KEY ("id_motivo_gratuidad") ); CREATE TABLE "operacion_servicio" ( "id_operacion_servicio" BIGINT NOT NULL, "id_operacion" BIGINT NOT NULL, "id_servicio" BIGINT NOT NULL, "id_motivo_gratuidad" BIGINT NULL, "id_regla_comision" BIGINT NULL, "id_autorizado_por" BIGINT NULL, "cantidad" INTEGER NOT NULL DEFAULT 1 CHECK (cantidad > 0), "precio_normal" NUMERIC(12,2) NOT NULL CHECK (precio_normal >= 0), "precio_aplicado" NUMERIC(12,2) NOT NULL CHECK (precio_aplicado >= 0), "motivo_descuento" VARCHAR(200) NULL, "comentario_descuento" TEXT NULL, "elegible_fidelidad_aplicado" BOOLEAN NOT NULL, "base_comision" NUMERIC(12,2) NOT NULL CHECK (base_comision >= 0), "monto_comision" NUMERIC(12,2) NOT NULL CHECK (monto_comision >= 0), PRIMARY KEY ("id_operacion_servicio"), CONSTRAINT "FK_operacion_servicio_id_operacion_servicio" FOREIGN KEY ("id_operacion_servicio") REFERENCES "usuario"("id_usuario"), CONSTRAINT "FK_operacion_servicio_id_regla_comision" FOREIGN KEY ("id_regla_comision") REFERENCES "operacion"("idempotency_key"), CONSTRAINT "FK_operacion_servicio_cantidad" FOREIGN KEY ("cantidad") REFERENCES "regla_comision"("vigencia_hasta"), CONSTRAINT "FK_operacion_servicio_precio_aplicado" FOREIGN KEY ("precio_aplicado") REFERENCES "motivo_gratuidad"("codigo") ); CREATE TABLE "inventario_sucursal" ( "id_inventario_sucursal" BIGINT NOT NULL, "id_sucursal" BIGINT NOT NULL; UNIQUE(id_sucursal, id_producto), "id_producto" BIGINT NOT NULL, "stock_actual" NUMERIC(12,3) NOT NULL, "stock_minimo" NUMERIC(12,3) NOT NULL CHECK (stock_minimo >= 0), "updated_at" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("id_inventario_sucursal") ); CREATE TABLE "membresia_plan" ( "id_plan_membresia" BIGINT NOT NULL, "codigo" VARCHAR(40) NOT NULL UNIQUE, "nombre" VARCHAR(100) NOT NULL, "precio" NUMERIC(12,2) NOT NULL CHECK (precio >= 0), "cantidad_servicios" INTEGER NOT NULL CHECK (cantidad_servicios > 0), "vigencia_desde" TIMESTAMPTZ NOT NULL, "vigencia_hasta" TIMESTAMPTZ NULL, "activo" BOOLEAN NOT NULL, "created_at" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("id_plan_membresia") ); CREATE TABLE "membresia_plan_servicio" ( "id_plan_servicio" BIGINT NOT NULL, "id_plan_membresia" BIGINT NOT NULL; UNIQUE(id_plan_membresia, id_servicio), "id_servicio" BIGINT NOT NULL, PRIMARY KEY ("id_plan_servicio"), CONSTRAINT "FK_membresia_plan_servicio_id_plan_servicio" FOREIGN KEY ("id_plan_servicio") REFERENCES "membresia_plan"("precio"), CONSTRAINT "FK_membresia_plan_servicio_id_plan_servicio" FOREIGN KEY ("id_plan_servicio") REFERENCES "servicio"("created_at") ); CREATE TABLE "movimiento_inventario" ( "id_movimiento_inventario" BIGINT NOT NULL, "id_sucursal" BIGINT NOT NULL, "id_producto" BIGINT NOT NULL, "id_operacion" BIGINT NULL, "id_operacion_producto" BIGINT NULL, "id_gasto" BIGINT NULL, "id_traslado" BIGINT NULL, "id_usuario_responsable" BIGINT NULL, "id_registrado_por" BIGINT NOT NULL, "tipo_movimiento" VARCHAR(40) NOT NULL, "cantidad" NUMERIC(12,3) NOT NULL CHECK (cantidad > 0), "fecha_hora" TIMESTAMPTZ NOT NULL, "observacion" TEXT NULL, PRIMARY KEY ("id_movimiento_inventario"), CONSTRAINT "FK_movimiento_inventario_id_registrado_por" FOREIGN KEY ("id_registrado_por") REFERENCES "operacion"("observaciones"), CONSTRAINT "FK_movimiento_inventario_fecha_hora" FOREIGN KEY ("fecha_hora") REFERENCES "gasto"("id_gasto"), CONSTRAINT "FK_movimiento_inventario_id_operacion" FOREIGN KEY ("id_operacion") REFERENCES "usuario"("nombre_completo"), CONSTRAINT "FK_movimiento_inventario_id_gasto" FOREIGN KEY ("id_gasto") REFERENCES "usuario"("nombre_completo"), CONSTRAINT "FK_movimiento_inventario_id_movimiento_inventario" FOREIGN KEY ("id_movimiento_inventario") REFERENCES "sucursal"("nombre") ); CREATE TABLE "producto" ( "id_producto" BIGINT NOT NULL, "nombre" VARCHAR(120) NOT NULL, "categoria" VARCHAR(80) NULL, "unidad_medida" VARCHAR(30) NOT NULL, "precio_venta_actual" NUMERIC(12,2) NULL, "activo" BOOLEAN NOT NULL, "created_at" TIMESTAMPTZ NOT NULL, "updated_at" TIMESTAMPTZ NULL, PRIMARY KEY ("id_producto") ); CREATE TABLE "operacion_producto" ( "id_operacion_producto" BIGINT NOT NULL, "id_operacion" BIGINT NOT NULL, "id_producto" BIGINT NOT NULL, "cantidad" NUMERIC(12,3) NOT NULL CHECK (cantidad > 0), "precio_unitario_aplicado" NUMERIC(12,2) NOT NULL CHECK (precio_unitario_aplicado >= 0), "total_linea" NUMERIC(12,2) NOT NULL CHECK (total_linea >= 0), PRIMARY KEY ("id_operacion_producto"), CONSTRAINT "FK_operacion_producto_id_producto" FOREIGN KEY ("id_producto") REFERENCES "operacion"("id_operacion"), CONSTRAINT "FK_operacion_producto_id_producto" FOREIGN KEY ("id_producto") REFERENCES "producto"("unidad_medida") ); CREATE TABLE "traslado_inventario" ( "id_traslado" BIGINT NOT NULL, "id_sucursal_origen" BIGINT NOT NULL, "id_sucursal_destino" BIGINT NOT NULL, "id_responsable" BIGINT NOT NULL, "idempotency_key" UUID NOT NULL UNIQUE, "fecha_hora" TIMESTAMPTZ NOT NULL, "observacion" TEXT NULL, "" <type>, PRIMARY KEY ("id_traslado"), CONSTRAINT "FK_traslado_inventario_observacion" FOREIGN KEY ("observacion") REFERENCES "usuario"("created_at"), CONSTRAINT "FK_traslado_inventario_id_responsable" FOREIGN KEY ("id_responsable") REFERENCES "sucursal"("updated_at") ); CREATE TABLE "membresia" ( "id_membresia" BIGINT NOT NULL, "id_cliente" BIGINT NOT NULL, "id_plan_membresia" BIGINT NOT NULL, "id_operacion_compra" BIGINT NULL, "fecha_compra" TIMESTAMPTZ NOT NULL, "fecha_activacion" TIMESTAMPTZ NOT NULL, "precio_pagado" NUMERIC(12,2) NOT NULL CHECK (precio_pagado >= 0), "servicios_iniciales" INTEGER NOT NULL CHECK (servicios_iniciales > 0), "estado" VARCHAR(30) NOT NULL, "created_at" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("id_membresia"), CONSTRAINT "FK_membresia_id_membresia" FOREIGN KEY ("id_membresia") REFERENCES "operacion"("observaciones") ); CREATE TABLE "membresia_consumo" ( "id_membresia_consumo" BIGINT NOT NULL, "id_membresia" BIGINT NOT NULL, "id_operacion_servicio" BIGINT NOT NULL UNIQUE, "cantidad" INTEGER NOT NULL DEFAULT 1 CHECK (cantidad > 0), "fecha_consumo" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("id_membresia_consumo"), CONSTRAINT "FK_membresia_consumo_id_membresia" FOREIGN KEY ("id_membresia") REFERENCES "operacion_servicio"("base_comision"), CONSTRAINT "FK_membresia_consumo_id_membresia" FOREIGN KEY ("id_membresia") REFERENCES "membresia"("estado") ); CREATE TABLE "cita_servicio" ( "id_cita_servicio" BIGINT NOT NULL, "id_cita" BIGINT NOT NULL, "id_servicio" BIGINT NOT NULL, "cantidad" INTEGER NOT NULL DEFAULT 1 CHECK (cantidad > 0), "observacion" TEXT NULL, PRIMARY KEY ("id_cita_servicio"), CONSTRAINT "FK_cita_servicio_id_cita" FOREIGN KEY ("id_cita") REFERENCES "cita"("id_creada_por") ); CREATE TABLE "usuario_sucursal" ( "id_usuario_sucursal" BIGINT NOT NULL, "id_usuario" BIGINT NOT NULL; UNIQUE(id_usuario, id_sucursal), "id_sucursal" BIGINT NOT NULL, "es_principal" BOOLEAN NOT NULL, "activo" BOOLEAN NOT NULL, "created_at" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("id_usuario_sucursal") ); CREATE TABLE "banco" ( "id_banco" BIGINT NOT NULL, "codigo" VARCHAR(40) NOT NULL UNIQUE, "nombre" VARCHAR(120) NOT NULL, "activo" BOOLEAN NOT NULL, PRIMARY KEY ("id_banco") ); CREATE TABLE "metodo_pago" ( "id_metodo_pago" BIGINT NOT NULL, "codigo" VARCHAR(40) NOT NULL UNIQUE, "nombre" VARCHAR(80) NOT NULL, "activo" BOOLEAN NOT NULL, PRIMARY KEY ("id_metodo_pago") ); CREATE TABLE "pago" ( "id_pago" BIGINT NOT NULL, "id_operacion" BIGINT NOT NULL UNIQUE, "id_metodo_pago" BIGINT NOT NULL, "id_banco" BIGINT NULL, "id_registrado_por" BIGINT NOT NULL, "monto" NUMERIC(12,2) NOT NULL CHECK (monto >= 0), "efectivo_recibido" NUMERIC(12,2) NULL, "cambio" NUMERIC(12,2) NULL, "referencia_transferencia" VARCHAR(180) NULL, "fecha_hora" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("id_pago"), CONSTRAINT "FK_pago_id_registrado_por" FOREIGN KEY ("id_registrado_por") REFERENCES "usuario"("firebase_uid"), CONSTRAINT "FK_pago_id_pago" FOREIGN KEY ("id_pago") REFERENCES "banco"("codigo"), CONSTRAINT "FK_pago_id_registrado_por" FOREIGN KEY ("id_registrado_por") REFERENCES "metodo_pago"("codigo") ); CREATE TABLE "movimiento_caja" ( "id_movimiento_caja" BIGINT NOT NULL, "id_sucursal" BIGINT NOT NULL, "id_pago" BIGINT NULL, "id_gasto" BIGINT NULL, "id_cuadre_caja" BIGINT NULL, "id_usuario" BIGINT NOT NULL, "tipo_movimiento" VARCHAR(30) NOT NULL, "monto" NUMERIC(12,2) NOT NULL CHECK (monto > 0), "fecha_hora" TIMESTAMPTZ NOT NULL, "observacion" TEXT NULL, PRIMARY KEY ("id_movimiento_caja"), CONSTRAINT "FK_movimiento_caja_id_usuario" FOREIGN KEY ("id_usuario") REFERENCES "gasto"("observacion"), CONSTRAINT "FK_movimiento_caja_id_pago" FOREIGN KEY ("id_pago") REFERENCES "pago"("referencia_transferencia"), CONSTRAINT "FK_movimiento_caja_id_movimiento_caja" FOREIGN KEY ("id_movimiento_caja") REFERENCES "usuario"("activo"), CONSTRAINT "FK_movimiento_caja_fecha_hora" FOREIGN KEY ("fecha_hora") REFERENCES "cuadre_caja"("periodo_fin") ); CREATE TABLE "bitacora_auditoria" ( "id_auditoria" BIGINT NOT NULL, "id_usuario" BIGINT NOT NULL, "id_sucursal" BIGINT NULL, "entidad" VARCHAR(80) NOT NULL, "id_registro" BIGINT NOT NULL, "accion" VARCHAR(50) NOT NULL, "valor_anterior" JSONB NULL, "valor_nuevo" JSONB NULL, "motivo" TEXT NULL, "fecha_hora" TIMESTAMPTZ NOT NULL, PRIMARY KEY ("id_auditoria") );
